    // and a new sign-in replaces it; either way the docked agent rebuilds.
    if (agent_settings() != agent_before)
        reload_agent_config();
}

"""Signing in to JusPrin from inside the desktop app, by email.

The app asks for an address; the server answers whether that address signs in
with a password or with a code it has just emailed. A correct code or password
ends in the same thing the browser sign-in ends in: an OAuth2 access token for
the JusPrin 2 application, so the app checks and stores it the same way.

Codes are six digits, live ten minutes, are used once, allow five tries and are
kept only as an HMAC in Redis. Answering "password" reveals that an account
exists; that is the convention, and it was chosen deliberately.
"""
import hashlib
import hmac
import json
import secrets
import time
from datetime import timedelta

from allauth.account.adapter import get_adapter
from allauth.account.models import EmailAddress
from django.conf import settings
from django.contrib.auth.models import update_last_login
from django.core.exceptions import ValidationError
from django.core.validators import validate_email
from django.db import transaction
from django.db.models import F
from django.http import HttpResponse, JsonResponse
from django.utils import timezone
from django.views.decorators.csrf import csrf_exempt
from django.views.decorators.http import require_POST
from ipware import get_client_ip
from oauth2_provider.models import AccessToken, Application, RefreshToken
from oauth2_provider.settings import oauth2_settings
from oauthlib.common import generate_token

from app.models import User
from lib.cache import REDIS
from lib.syndicate import syndicate_from_request

from .errors import error_body

KEY_PREFIX = 'jusprin:v2:sign_in'
CODE_SECONDS = 10 * 60
CODE_TRIES = 5
CODES_PER_ADDRESS_PER_HOUR = 5
CODES_PER_IP_PER_HOUR = 20
PASSWORDS_PER_ADDRESS_PER_HOUR = 10
SCOPE = 'read write'


def _refuse(code: str, status: int, message: str = None, details: dict = None) -> HttpResponse:
    return HttpResponse(error_body(code, message, details), status=status, content_type='application/json')


def _email(request):
    """The address in the JSON body, lowercased, or None when it is missing or
    not an address."""
    try:
        email = json.loads(request.body).get('email', '')
    except (json.JSONDecodeError, AttributeError):
        return None
    if not isinstance(email, str):
        return None
    email = email.strip().lower()
    try:
        validate_email(email)
    except ValidationError:
        return None
    return email


def _field(request, name: str) -> str:
    value = json.loads(request.body).get(name, '')
    return value if isinstance(value, str) else ''


def _over_limit(key: str, limit: int) -> bool:
    """Counts one more attempt in this hour's bucket; True past the limit."""
    bucket = f'{KEY_PREFIX}:{key}:{int(time.time() // 3600)}'
    pipe = REDIS.pipeline()
    pipe.incr(bucket)
    pipe.expire(bucket, 3600)
    count, _ = pipe.execute()
    return count > limit


def _account(request, email: str):
    """The account this address signs in to, or None.

    ACCOUNT_UNIQUE_EMAIL is False and User is unique on (email, syndicate) only
    as typed, so one address can own several accounts in a syndicate that
    differ in letter case. The choice is deterministic: active accounts in the
    request's syndicate with that address, case-insensitive, the most recently
    signed-in first, then the newest.
    """
    return (User.objects.filter(email__iexact=email, syndicate=syndicate_from_request(request), is_active=True)
            .order_by(F('last_login').desc(nulls_last=True), '-id').first())


def _signs_in_with_password(user) -> bool:
    # An account made through Google gets a random password its owner never
    # saw (SocialAccountAdapter), so a social account means code, not password.
    return user is not None and user.has_usable_password() and not user.socialaccount_set.exists()


def _digest(email: str, code: str) -> str:
    return hmac.new(settings.SECRET_KEY.encode(), f'{email}:{code}'.encode(), hashlib.sha256).hexdigest()


def _send_code(request, email: str):
    """Emails a new code, replacing any earlier one. Returns a refusal when the
    address or the client has had too many codes this hour, else None."""
    client_ip, _ = get_client_ip(request)
    if _over_limit(f'codes:{email}', CODES_PER_ADDRESS_PER_HOUR) or \
            _over_limit(f'codes_ip:{client_ip}', CODES_PER_IP_PER_HOUR):
        return _refuse('too_many_codes', 429)
    code = f'{secrets.randbelow(10 ** 6):06d}'
    key = f'{KEY_PREFIX}:code:{email}'
    pipe = REDIS.pipeline()
    pipe.delete(key)
    pipe.hset(key, mapping={'digest': _digest(email, code), 'tries': 0})
    pipe.expire(key, CODE_SECONDS)
    pipe.execute()
    get_adapter(request).send_mail('jusprin/v2/email/sign_in_code', email, {'code': code})
    return None


def _token_response(user) -> JsonResponse:
    """A new access and refresh token for the JusPrin 2 application, as the
    authorization code grant mints them (oauth2_validators.save_bearer_token)."""
    application = Application.objects.get(client_id=settings.JUSPRIN_V2_OAUTH_CLIENT_ID)
    expires_in = oauth2_settings.ACCESS_TOKEN_EXPIRE_SECONDS
    with transaction.atomic():
        access = AccessToken.objects.create(user=user, application=application, token=generate_token(),
                                            expires=timezone.now() + timedelta(seconds=expires_in), scope=SCOPE)
        refresh = RefreshToken.objects.create(user=user, application=application, token=generate_token(),
                                              access_token=access)
    update_last_login(None, user)
    response = JsonResponse({'access_token': access.token, 'refresh_token': refresh.token,
                             'expires_in': expires_in, 'token_type': 'Bearer', 'scope': SCOPE})
    response['Cache-Control'] = 'no-store'
    return response


def _new_account(request, email: str):
    """Makes the account for an address that has none, the way
    SocialAccountAdapter does, with no usable password."""
    syndicate = syndicate_from_request(request)
    user = User(email=email, username=f'{email}_{syndicate.id}', syndicate=syndicate, is_active=True)
    user.set_unusable_password()
    user.save()
    return user


@csrf_exempt
@require_POST
def email(request):
    """Body {"email"}. Answers {"method": "password"} for an account that has
    a password, else emails a code and answers {"method": "code"}."""
    address = _email(request)
    if address is None:
        return _refuse('invalid_request', 400)
    if _signs_in_with_password(_account(request, address)):
        return JsonResponse({'method': 'password'})
    refused = _send_code(request, address)
    return refused or JsonResponse({'method': 'code'})


@csrf_exempt
@require_POST
def resend(request):
    """Body {"email"}. Emails a new code, whatever the address signs in with:
    it also serves "Email me a code instead" on the password step."""
    address = _email(request)
    if address is None:
        return _refuse('invalid_request', 400)
    return _send_code(request, address) or HttpResponse(status=204)


@csrf_exempt
@require_POST
def code(request):
    """Body {"email", "code"}. Signs in, making the account for a new address."""
    address = _email(request)
    if address is None:
        return _refuse('invalid_request', 400)
    key = f'{KEY_PREFIX}:code:{address}'
    stored = REDIS.hgetall(key)
    if not stored:
        return _refuse('expired_code', 400)
    if int(stored['tries']) >= CODE_TRIES:
        return _refuse('too_many_tries', 429)
    if not hmac.compare_digest(stored['digest'], _digest(address, _field(request, 'code').strip())):
        tries = REDIS.hincrby(key, 'tries', 1)
        if tries >= CODE_TRIES:
            return _refuse('too_many_tries', 429)
        return _refuse('wrong_code', 400, details={'tries_left': CODE_TRIES - tries})
    # Used once: of two requests with the right code, only one deletes it.
    if not REDIS.delete(key):
        return _refuse('expired_code', 400)

    with transaction.atomic():
        user = _account(request, address)
        if user is None:
            if User.objects.filter(email__iexact=address, syndicate=syndicate_from_request(request)).exists():
                # Only a deactivated account holds this address; it stays deactivated.
                return _refuse('account_inactive', 403)
            user = _new_account(request, address)
        verified, _ = EmailAddress.objects.get_or_create(
            user=user, email__iexact=address, defaults={'email': address, 'primary': not user.emailaddress_set.exists()})
        if not verified.verified:
            verified.verified = True
            verified.save(update_fields=['verified'])
    return _token_response(user)


@csrf_exempt
@require_POST
def password(request):
    """Body {"email", "password"}."""
    address = _email(request)
    if address is None:
        return _refuse('invalid_request', 400)
    if _over_limit(f'passwords:{address}', PASSWORDS_PER_ADDRESS_PER_HOUR):
        return _refuse('too_many_tries', 429)
    user = _account(request, address)
    # Not django.contrib.auth.authenticate: SyndicateSpecificBackend uses .get()
    # on the address and raises when two accounts share it. The account is
    # chosen as _account() chooses it, then checked as that backend checks it.
    if not _signs_in_with_password(user) or not user.check_password(_field(request, 'password')):
        return _refuse('wrong_password', 401)
    return _token_response(user)
